cat > /tmp/probe.py << 'PY'
import subprocess, sys
def run(mode, s):
    if isinstance(s,str): s=s.encode()
    p=subprocess.run(["./executable",mode,""], input=s, capture_output=True)
    return p.stdout, p.returncode, p.stderr
def T(s):
    out,rc,err=run("--transform",s)
    return out.decode('utf-8','backslashreplace')
def S(s, mode="--syntax"):
    out,rc,err=run(mode,s)
    return out
if __name__=="__main__":
    for c in sys.argv[1:]:
        print(repr(c), "=>", repr(T(c+"
")))
PY
