DIGITS = b"0123456789"
WS_NO_NL = b" \t\r\x0b\x0c"

class Atom:
    __slots__=("text","color","kind")
    def __init__(self,text,color=NORMAL,kind="orig"):
        self.text=text; self.color=color; self.kind=kind
    def __repr__(self):
        return f"Atom({self.text!r},{self.color},{self.kind})"

class Pitfall(Exception):
    def __init__(self,pos,length):
        self.pos=pos; self.length=length

class Segment:
    __slots__=("type","start","end","atoms","name","safe","simple_name","braced","star","unclosed","open_atom","close_atom","content_segments","subscript_star_atom","cluster_start","cluster_end")
    def __init__(self,typ,start):
