            a=self.emit(b"$",plain_color if container=="word" else (DQ if container=="dq" else (ARITH if container=="arith" else plain_color)))
            self.i+=1
            seg=Segment("plain",start); seg.atoms=[a] if a else []; seg.end=self.i; return seg
        nxt=self.data[self.i+1]
        if nxt==0x27 and container!="dq": # $'
            return self.parse_ansic()
        if container=="dq" and nxt==0x27:
            a=self.emit(b"$",DQ); self.i+=1; seg=Segment("plain",start); seg.atoms=[a]; seg.end=self.i; return seg
        if nxt==0x22: # $"
            col=plain_color if container=="word" else (DQ if container=="dq" else (ARITH if container=="arith" else plain_color))
            a=self.emit(b"$",col); self.i+=1; seg=Segment("plain",start); seg.atoms=[a] if a else []; seg.end=self.i; return seg
        if nxt==0x7b: # {
            return self.parse_braced()
        if nxt==0x28: # (
            if self.i+2<self.n and self.data[self.i+2]==0x28:
                return self.parse_arith(b"$ ((", "parens") if False else self.parse_arith(b"$(( ","parens".encode() if False else None) if False else self._parse_arith_segment(b"$((",b"parens")
            else:
                return self.parse_cmdsubst()
        if nxt==0x5b: # [
            return self.parse_oldarith(container)
        if nxt in DIGITS:
            # pitfall if second digit
            if self.i+2<self.n and self.data[self.i+2] in DIGITS:
                ln=1
                j=self.i+1
                while j<self.n and self.data[j] in DIGITS:
                    ln+=1; j+=1
                raise Pitfall(self.i,ln)
            a1=self.emit(b"$",VAR); a2=self.emit(bytes([nxt]),VAR); self.i+=2
            seg=Segment("var",start); seg.atoms=[a1,a2]; seg.name=bytes([nxt]); seg.end=self.i; return seg
        if nxt in IDENT_START:
            j=self.i+1
            while j<self.n and self.data[j] in IDENT_CONT:
                j+=1
            name=self.data[self.i+1:j]
            a1=self.emit(b"$",VAR); a2=self.emit(name,VAR); self.i=j
            seg=Segment("var",start); seg.atoms=[a1,a2]; seg.name=name; seg.simple_name=True; seg.end=self.i; return seg
        if nxt in b"@*":
            a1=self.emit(b"$",VAR); a2=self.emit(bytes([nxt]),VAR); self.i+=2
            seg=Segment("var",start); seg.atoms=[a1,a2]; seg.name=bytes([nxt]); seg.star=(nxt==0x2a); seg.end=self.i; return seg
        if nxt in b"#?$!":
            a1=self.emit(b"$",VAR); a2=self.emit(bytes([nxt]),VAR); self.i+=2
            seg=Segment("var",start); seg.atoms=[a1,a2]; seg.name=bytes([nxt]); seg.safe=True; seg.end=self.i; return seg
        if nxt==0x2d: # -
            a1=self.emit(b"$",VAR); a2=self.emit(b"-",VAR); self.i+=2
            seg=Segment("var",start); seg.atoms=[a1,a2]; seg.name=b"-"; seg.end=self.i; return seg
        # literal $
        col=plain_color if container=="word" else (DQ if container=="dq" else (ARITH if container=="arith" else plain_color))
        a=self.emit(b"$",col); self.i+=1; seg=Segment("plain",start); seg.atoms=[a] if a else []; seg.end=self.i; return seg

    def parse_braced(self):
        start=self.i
        seg=Segment("var",start); seg.braced=True
        # special subscript pattern ${name[${
        special=False
        # lookahead detect name [ ${
        j0=self.i+2; k=j0
        if k<self.n and self.data[k] in IDENT_START:
            while k<self.n and self.data[k] in IDENT_CONT: k+=1
        elif k<self.n and self.data[k] in DIGITS:
            while k<self.n and self.data[k] in DIGITS: k+=1
        if self.data[k:k+3]==b"[${":
            special=True
        depth=1; j=self.i+2; closed=False; close_pos=-1
        while j<self.n:
            c=self.data[j]
            if c==0x5c:
                j+=2; continue
            if not special and self.data[j:j+2]==b"${":
                depth+=1; j+=2; continue
            if c==0x7d:
                depth-=1
                if depth==0:
                    closed=True; close_pos=j; break
                j+=1; continue
            j+=1
        if not closed:
            a=self.emit(self.data[self.i:],VAR); self.i=self.n; self.eof_error=True
            seg.unclosed=True; seg.atoms=[a]; seg.end=self.i; return seg
        content=self.data[self.i+2:close_pos]
        # atoms
        a1=self.emit(b"$",VAR); a2=self.emit(b"{",VAR)
        atoms=[a1,a2]
        # subscript star
        star_rel=-1
        # initial name token
        m=0
        if m<len(content) and content[m] in IDENT_START:
            while m<len(content) and content[m] in IDENT_CONT: m+=1
        elif m<len(content) and content[m] in DIGITS:
            while m<len(content) and content[m] in DIGITS: m+=1
        else:
            m=0
        if m>0 and content[m:m+2]==b"[*":
            star_rel=m+1
        if star_rel>=0:
            before=content[:star_rel]; starb=content[star_rel:star_rel+1]; after=content[star_rel+1:]
            if before: atoms.append(self.emit(before,VAR))
            sa=self.emit(starb,VAR); atoms.append(sa); seg.subscript_star_atom=sa
            if after: atoms.append(self.emit(after,VAR))
        else:
            if content: atoms.append(self.emit(content,VAR))
        a3=self.emit(b"}",VAR); atoms.append(a3)
        seg.atoms=atoms; seg.open_atom=a2; seg.close_atom=a3
        seg.name=content
        if len(content)>0 and content[0] in b"#!?$":
            seg.safe=True
        # simple identifier?
        if len(content)>0 and content[0] in IDENT_START and all(ch in IDENT_CONT for ch in content):
            seg.simple_name=True
        self.i=close_pos+1; seg.end=self.i; return seg

    def parse_cmdsubst(self):
        start=self.i; seg=Segment("cmdsubst",start)
        a=self.emit(b"$(",NORMAL); seg.atoms=[a]; self.i+=2
        start_atoms=len(self.atoms)
        res=self.parse_body(BodyCtx(end_kind=")",initial_state="cmd"))
        seg.atoms=self.atoms[start_atoms-1:] if False else seg.atoms+self.atoms[start_atoms:]
        # atoms attribute: include opening + body atoms (already collected body atoms through global)
        # Reconstruct as slice from the opening atom
        idx=self.atoms.index(a); seg.atoms=self.atoms[idx:]
        if res.reason!="closed":
            seg.unclosed=True
        seg.end=self.i; return seg

    def parse_backtick(self):
        start=self.i; seg=Segment("backtick",start)
        a=self.emit(b"`",NORMAL); seg.open_atom=a; self.i+=1
        res=self.parse_body(BodyCtx(end_kind="`",initial_state="cmd"))
        if res.reason=="closed":
            seg.close_atom=self.atoms[-1] if self.atoms else None
        else:
            seg.unclosed=True
        idx=self.atoms.index(a); seg.atoms=self.atoms[idx:]
        seg.end=self.i; return seg

    def convert_backtick(self,seg):
        if seg.open_atom is not None and seg.open_atom.kind!="del":
            seg.open_atom.kind="del"
            self.insert_after(seg.open_atom,b"$(")
        if seg.close_atom is not None and seg.close_atom.kind!="del":
            seg.close_atom.kind="del"
            self.insert_after(seg.close_atom,b")")

    def _parse_arith_segment(self,opening,close_mode):
        # opening is b"$((", b"((", or b"[["
        start=self.i; seg=Segment("arith",start)
        if close_mode==b"parens":
            a=self.emit(opening,ARITH); seg.atoms=[a]; self.i+=len(opening)
            depth=0; closed=False
            while self.i<self.n:
                if self.startswith(b"<<") and not self.startswith(b"<<<"):
                    if self.try_heredoc(): continue
                c=self.data[self.i]
                if c==0x24: # $
                    s=self.parse_dollar(container="arith"); continue
                if c==0x27:
                    self.parse_sq(); continue
                if c==0x22:
                    self.parse_dq(); continue
                if c==0x60:
                    self.parse_backtick(); continue
                if c==0x5c:
                    self.parse_escape(); continue
                if c==0x28: # (
                    depth+=1; self.emit(b"(",ARITH); self.i+=1; continue
                if c==0x29: # )
                    if depth==0 and self.startswith(b"))"):
                        self.emit(b"))",ARITH); self.i+=2; closed=True; break
                    if depth>0: depth-=1
                    self.emit(b")",ARITH); self.i+=1; continue
                self.emit(bytes([c]),ARITH); self.i+=1
            if not closed:
                self.eof_error=True; seg.unclosed=True
        else: # brackets [[
            a=self.emit(opening,ARITH); seg.atoms=[a]; self.i+=len(opening)
            bdepth=2; closed=False
            while self.i<self.n:
                if self.startswith(b"<<") and not self.startswith(b"<<<"):
                    if self.try_heredoc(): continue
                c=self.data[self.i]
                if c==0x24:
                    s=self.parse_dollar(container="arith"); continue
                if c==0x27:
                    self.parse_sq(); continue
                if c==0x22:
                    self.parse_dq(); continue
                if c==0x60:
                    self.parse_backtick(); continue
                if c==0x5c:
                    self.parse_escape(); continue
                if c==0x5b: # [
                    bdepth+=1; self.emit(b"[",ARITH); self.i+=1; continue
                if c==0x5d: # ]
                    bdepth-=1; self.emit(b"]",ARITH); self.i+=1
                    if bdepth==0:
                        closed=True; break
                    continue
                self.emit(bytes([c]),ARITH); self.i+=1
            if not closed:
                self.eof_error=True; seg.unclosed=True
        seg.end=self.i; return seg

    def parse_arith(self,opening,mode):
        return self._parse_arith_segment(opening,mode)

    def parse_oldarith(self,container="word"):
        start=self.i; seg=Segment("oldarith",start)
        a=self.emit(b"$[",NORMAL); self.i+=2; seg.atoms=[a]
        word_mode="hazard" if container=="word" else "safe"
        res=self.parse_body(BodyCtx(end_kind="]",initial_state="arg",lenient_eof=True,word_mode=word_mode))
        idx=self.atoms.index(a); seg.atoms=self.atoms[idx:]
        seg.end=self.i; return seg

    def parse_dq(self,seg_start=None):
        start=self.i; seg=Segment("dq",start)
        open_atom=self.emit(b'"',DQ); seg.open_atom=open_atom; self.i+=1
        closed=False
        while self.i<self.n:
            c=self.data[self.i]
            if c==0x22:
                seg.close_atom=self.emit(b'"',DQ); self.i+=1; closed=True; break
            if c==0x5c:
                s=self.parse_escape(); seg.content_segments.append(s); continue
            if c==0x60:
                s=self.parse_backtick(); seg.content_segments.append(s); self.convert_backtick(s); continue
            if c==0x24:
                s=self.parse_dollar(container="dq",plain_color=DQ); seg.content_segments.append(s); continue
            # plain run
            j=self.i
            while j<self.n and self.data[j] not in b'"$`\\':
                j+=1
            a=self.emit(self.data[self.i:j],DQ); s=Segment("plain",self.i); s.atoms=[a] if a else []; s.end=j; seg.content_segments.append(s); self.i=j
        if not closed:
            self.eof_error=True; seg.unclosed=True
        # sole braced var brace removal
        if closed and len(seg.content_segments)==1:
            cs=seg.content_segments[0]
            if cs.type=="var" and cs.braced and cs.simple_name:
                # need brace?
                k=self.i
                while k<self.n and self.data[k]==0x22: k+=1
                need=False
                if k<self.n and self.data[k] in IDENT_CONT: need=True
                if not need:
                    if cs.open_atom: cs.open_atom.kind="del"
                    if cs.close_atom: cs.close_atom.kind="del"
        seg.end=self.i
        idx=self.atoms.index(open_atom); seg.atoms=self.atoms[idx:]
        return seg

    def parse_paren_segment(self,word_role):
        start=self.i; seg=Segment("paren",start)
        a=self.emit(b"(",NORMAL); self.i+=1
        res=self.parse_body(BodyCtx(end_kind=")",initial_state=("cmd" if word_role=="cmd" else "arg"),lenient_eof=True))
        if res.reason=="closed":
            seg.close_atom=self.atoms[-1]
        idx=self.atoms.index(a); seg.atoms=self.atoms[idx:]
        seg.end=self.i; return seg

    # --- word parsing ---
    def word_terminator(self,c,role,body_ctx,extra):
        if c<=0x20: return True
        if c in b";&|": return True
        if c==0x23: return True # #
        if extra and c in extra: return True
        if c==0x29: # )
            if extra and 0x29 in extra: return True
            if role=="cmd": return True
            if body_ctx is not None and body_ctx.end_kind in (")","]"): return True
            return False
        if body_ctx is not None and body_ctx.end_kind=="]" and c==0x5d: return True
        if body_ctx is not None and body_ctx.end_kind=="`" and c==0x60: return True
        return False

    def parse_word_segments(self,mode,plain_color,role,body_ctx,extra=b""):
        # returns (segments, clusters, end_reason)
        segments=[]; clusters=[]
        cluster_open=False; cluster_start_idx=-1; cluster_close_atom=None
        end_reason="eof"
        while self.i<self.n:
            c=self.data[self.i]
            if self.word_terminator(c,role,body_ctx,extra):
                end_reason="terminator"; break
            # heredoc mid-word
            if self.startswith(b"<<") and not self.startswith(b"<<<"):
                if self.try_heredoc():
                    end_reason="heredoc"; break
                else:
                    # treat << as plain
                    a=self.emit(b"<<",plain_color); self.i+=2; s=Segment("plain",self.i-2); s.atoms=[a]; segments.append(s); continue
            seg_start_idx=len(segments)
            seg=None; start=self.i
            if c==0x5c:
                seg=self.parse_escape()
            elif c==0x27:
                seg=self.parse_sq()
            elif c==0x22:
                # dq, possibly merged
                if mode=="hazard" and cluster_open:
                    seg=self.parse_dq()
                    # merge: delete opening
                    if seg.open_atom: seg.open_atom.kind="del"
                    # cluster closes at dq close
                    cluster_open=False
                    if clusters and clusters[-1][1] is None:
                        clusters[-1]=(clusters[-1][0],seg_start_idx,seg.close_atom)
                    segments.append(seg)
                    if seg.unclosed: end_reason="eof"; break
                    continue
                else:
                    seg=self.parse_dq()
            elif c==0x60:
                seg=self.parse_backtick()
            elif c==0x24:
                seg=self.parse_dollar(container="word",plain_color=plain_color)
            elif c==0x28 and role!="cmd": # (
                seg=self.parse_paren_segment(role)
            elif c==0x28 and role=="cmd":
                end_reason="terminator"; break
            else:
                # plain run
                j=self.i
                while j<self.n:
                    ch=self.data[j]
                    if ch<=0x20 or ch in b";&|#\\'\"`$": break
                    if extra and ch in extra: break
                    if ch==0x28: break # ( segment/terminator
                    if ch==0x29:
                        if self.word_terminator(ch,role,body_ctx,extra): break
                        j+=1; continue
                    if body_ctx is not None and body_ctx.end_kind=="]" and ch==0x5d: break
                    if body_ctx is not None and body_ctx.end_kind=="`" and ch==0x60: break
                    if self.data[j:j+2]==b"<<" and self.data[j:j+3]!=b"<<<": break
                    j+=1
                if j==self.i:
                    # single char fallback (e.g. '(' in cmd handled, or other)
                    j=self.i+1
                a=self.emit(self.data[self.i:j],plain_color); seg=Segment("plain",start); seg.atoms=[a] if a else []; seg.end=j; self.i=j
            if seg is None:
                break
            segments.append(seg)
            # quotification processing
            if mode=="hazard":
                # classify
                is_unsafe=False; is_other=False; is_safe_seg=False
                if seg.type=="var" and not seg.safe: is_unsafe=True
                elif seg.type in ("cmdsubst","backtick"): is_unsafe=True
                elif seg.type=="var" and seg.safe: is_safe_seg=True
                elif seg.type=="arith": is_safe_seg=True
                elif seg.type in ("dq",): is_other=True
                else: is_other=True
                if is_unsafe:
                    started=False
                    if not cluster_open:
                        # insert opening quote before seg first atom
                        if seg.atoms:
                            self.insert_before(seg.atoms[0],b'"')
                        else:
                            self.emit(b'"',NORMAL,"ins")
                        cluster_open=True; cluster_start_idx=seg_start_idx; started=True; clusters.append((seg_start_idx,None,None))
                    # normalization
                    if seg.type=="backtick":
                        self.convert_backtick(seg)
                    if seg.type=="var":
                        # $* conversion if started cluster
                        if seg.star and started:
                            # delete *, insert @
                            if len(seg.atoms)>=2:
                                seg.atoms[1].kind="del"; self.insert_after(seg.atoms[1],b"@")
                            # close cluster immediately
                            close_a=self.insert_after(seg.atoms[-1],b'"') if seg.atoms else self.emit(b'"',NORMAL,"ins")
                            cluster_open=False
                            if clusters: clusters[-1]=(clusters[-1][0],seg_start_idx,close_a)
                        else:
                            if seg.subscript_star_atom is not None:
                                seg.subscript_star_atom.kind="del"; self.insert_after(seg.subscript_star_atom,b"@")
                            if seg.simple_name:
                                self.apply_brace(seg)
                    # end unsafe
                elif is_safe_seg:
                    # stays in cluster if open
                    pass
                else:
                    # other segment
                    if seg.type=="plain":
                        if cluster_open:
                            # decide bridge
                            # lookahead next segment type
                            nxt_type=self.classify_next(self.i,role,body_ctx,extra)
                            quotable=True
                            # check bytes of this plain segment
                            txt=b"".join(aa.text for aa in seg.atoms if aa.kind!="ins")
                            if any(bb in txt for bb in b"*?%!#"):
                                quotable=False
                            if quotable and nxt_type in ("var","cmdsubst","backtick","arith","dq"):
                                pass # stay open
                            else:
                                if seg.atoms:
                                    self.insert_before(seg.atoms[0],b'"')
                                cluster_open=False
                                if clusters and clusters[-1][1] is None: clusters[-1]=(clusters[-1][0],seg_start_idx-1,None)
                    elif seg.type=="dq":
                        # handled above for merge; if not cluster_open, nothing
                        pass
                    else:
                        if cluster_open:
                            if seg.atoms:
                                self.insert_before(seg.atoms[0],b'"')
                            cluster_open=False
                            if clusters and clusters[-1][1] is None: clusters[-1]=(clusters[-1][0],seg_start_idx-1,None)
            if seg.unclosed or self.eof_error:
                # if a segment went to EOF, break (but continue? pos is EOF usually)
                if self.i>=self.n:
                    end_reason="eof"; break
                # sq/dq unclosed consume to EOF
                if seg.unclosed:
                    end_reason="eof"; break
        if mode=="hazard" and cluster_open:
            if not self.eof_error:
                self.emit(b'"',NORMAL,"ins")
                if clusters and clusters[-1][1] is None: clusters[-1]=(clusters[-1][0],len(segments)-1,None)
            # close
        return segments,clusters,end_reason

    def classify_next(self,pos,role,body_ctx,extra):
        if pos>=self.n: return None
        c=self.data[pos]
        if c<=0x20 or c in b";&|#": return None
        if extra and c in extra: return None
        if c==0x29 and self.word_terminator(c,role,body_ctx,extra): return None
        if c==0x5c: return "escape"
        if c==0x27: return "sq"
        if c==0x22: return "dq"
        if c==0x60: return "backtick"
        if c==0x28: return "paren"
        if c==0x24:
            if pos+1>=self.n: return "plain"
            nxt=self.data[pos+1]
            if nxt==0x27: return "ansic"
            if nxt==0x22: return "plain"
            if nxt==0x7b: return "var"
            if nxt==0x28:
                return "arith" if (pos+2<self.n and self.data[pos+2]==0x28) else "cmdsubst"
            if nxt==0x5b: return "oldarith"
            if nxt in IDENT_START or nxt in DIGITS or nxt in b"@*#?$!-": return "var"
            return "plain"
        return "plain"

    def apply_brace(self,seg):
        # seg is simple_name var (braced or unbraced) being quotified
        k=seg.end
        while k<self.n and self.data[k]==0x22: k+=1
        need=False
        if k>=self.n: need=True
        elif self.data[k] in IDENT_CONT: need=True
        if seg.braced:
            if not need:
                if seg.open_atom: seg.open_atom.kind="del"
                if seg.close_atom: seg.close_atom.kind="del"
        else:
            if need:
                if len(seg.atoms)>=2:
                    self.insert_after(seg.atoms[0],b"{")
                    self.insert_after(seg.atoms[1],b"}")

    def match_assignment(self):
        i=self.i
        if i>=self.n or self.data[i] not in IDENT_START: return None
        j=i+1
        while j<self.n and self.data[j] in IDENT_CONT: j+=1
        name_end=j
        if j<self.n and self.data[j]==0x5b: # [
            e=self.data.find(b"]",j+1)
            if e<0: return None
            j=e+1; name_end=j
        plus=False
        if j<self.n and self.data[j]==0x2b:
            plus=True; j+=1
        if j<self.n and self.data[j]==0x3d: # =
            return (name_end,j,plus) # name_end end of name, eqpos j
        return None

    def parse_word(self,role,body_ctx,mode_override=None,plain_color_override=None,extra=b""):
        start=self.i
        info=WordInfo(start)
        mode=mode_override if mode_override is not None else ("hazard" if (body_ctx.word_mode=="hazard" if body_ctx else True) else "safe")
        command_position=(role=="cmd")
        plain_color=plain_color_override if plain_color_override is not None else (COMMAND if command_position else NORMAL)
        if command_position:
            m=self.match_assignment()
            if m is not None:
                name_end,eqpos,plus=m
                # emit name
                self.emit(self.data[start:name_end],ASSIGN)
                # operator
                self.emit(self.data[name_end:eqpos+1],NORMAL); self.i=eqpos+1
                info.type="assignment"
                # RHS
                if self.i<self.n and self.data[self.i]==0x28: # (
                    self.emit(b"(",NORMAL); self.i+=1
                    self.parse_body(BodyCtx(end_kind=")",initial_state="arg"))
                    # continue RHS word
                    segs,clusters,er=self.parse_word_segments("safe",NORMAL,"assign",body_ctx,extra)
                    info.segments=segs
                else:
                    segs,clusters,er=self.parse_word_segments("safe",NORMAL,"assign",body_ctx,extra)
                    info.segments=segs
                info.end=self.i; return info
        segs,clusters,er=self.parse_word_segments(mode,plain_color,role,body_ctx,extra)
        info.segments=segs; info.clusters=clusters; info.end_reason=er; info.end=self.i
        # classification
        if command_position:
            if len(segs)==1 and segs[0].type=="plain":
                txt=b"".join(a.text for a in segs[0].atoms)
                stay={b"if",b"then",b"else",b"elif",b"fi",b"while",b"until",b"do",b"done",b"function",b"{",b"}",b"!",b"export",b"local",b"readonly",b"declare"}
                if txt in stay:
                    info.type="keyword"
                    for a in segs[0].atoms: a.color=KEYWORD
                elif txt in (b"for",b"select"):
                    info.type="for"
                    for a in segs[0].atoms: a.color=KEYWORD
                elif txt==b"case":
                    info.type="case"
                    for a in segs[0].atoms: a.color=KEYWORD
                else:
                    info.type="command"
            else:
                info.type="command" if segs else "empty"
        else:
            info.type="arg" if segs else "empty"
        return info

    # --- test special ---
    def parse_test_command(self,body_ctx):
        # at test / [
        if self.startswith(b"test "):
            a=self.emit(b"test ",COMMAND); self.i+=5; prefix=b"test"
        else:
            a=self.emit(b"[ ",COMMAND); self.i+=2; prefix=b"["
        # -n / -z
        if self.startswith(b"-n ") or self.startswith(b"-z "):
            flag=self.data[self.i+1:self.i+2]
            nxt_type=self.classify_next(self.i+3,"arg",body_ctx,b"")
            if nxt_type in ("dq","sq","ansic","escape","var","cmdsubst","backtick","arith"):
                # delete -n / -z + space
                self.emit(self.data[self.i:self.i+3],NORMAL,"del"); self.i+=3
                info=self.parse_word("arg",body_ctx)
                suffix=b' != ""' if flag==b"n" else b' = ""'
                # find unit end
                ref=self.unit_end_ref(info)
                if ref is not None:
                    self.insert_after(ref,suffix)
                else:
                    self.emit(suffix,NORMAL,"ins")
                return
            else:
                return
        # x pattern
        # parse word1
        if self.i>=self.n: return
        info1=self.parse_word("arg",body_ctx)
        if not self.x_left_qualifies(info1): return
        # separator exactly one space
        if not (self.i<self.n and self.data[self.i]==0x20): return
        # peek if next char after single space starts something and the following char after space is not space
        if self.i+1>=self.n or self.data[self.i+1]<=0x20: 
            # consume? let body handle; we already consumed word1, return
            return
        self.emit(b" ",NORMAL); self.i+=1
        info_op=self.parse_word("arg",body_ctx)
        if not (len(info_op.segments)==1 and info_op.segments[0].type=="plain" and b"".join(a.text for a in info_op.segments[0].atoms) in (b"=",b"==",b"!=")):
            return
        if not (self.i<self.n and self.data[self.i]==0x20): return
        if self.i+1>=self.n or self.data[self.i+1]<=0x20: return
        self.emit(b" ",NORMAL); self.i+=1
        info_r=self.parse_word("arg",body_ctx)
        if not self.x_right_qualifies(info_r): return
        # apply
        # left: delete x atom
        seg0=info1.segments[0]
        for a in seg0.atoms: a.kind="del"
        # right
        rseg0=info_r.segments[0]
        txt=b"".join(a.text for a in rseg0.atoms)
        if txt==b"x":
            for a in rseg0.atoms: a.kind="del"
            if len(info_r.segments)==1:
                # insert "" after x
                if rseg0.atoms: self.insert_after(rseg0.atoms[-1],b'""')
        else:
            # split first char
            if rseg0.atoms:
                a0=rseg0.atoms[0]
                # a0 text starts with x
                rest=a0.text[1:]
                a0.text=rest
                self.insert_before(a0,b"x").kind="del" if False else None
                # insert_before returns atom; set kind
                idx=self.atoms.index(a0); self.atoms[idx-1].kind="del"
        return

    def x_left_qualifies(self,info):
        segs=info.segments
        if len(segs)<2: return False
        if segs[0].type!="plain": return False
        if b"".join(a.text for a in segs[0].atoms)!=b"x": return False
        # unit starting at segs[1] must end at word end
        # find unit end segment index
        ue=self.unit_end_segment_index(info,1)
        return ue==len(segs)-1

    def x_right_qualifies(self,info):
        segs=info.segments
        if len(segs)<1: return False
        if segs[0].type!="plain": return False
        txt=b"".join(a.text for a in segs[0].atoms)
        return len(txt)>=1 and txt[:1]==b"x"

    def unit_end_segment_index(self,info,start_idx):
        segs=info.segments
        if start_idx>=len(segs): return -1
        seg=segs[start_idx]
        if seg.type in ("dq","sq","ansic","escape","arith","oldarith","paren","plain"):
            return start_idx
        if seg.type=="var" and seg.safe:
            return start_idx
        # unsafe var/cmdsubst/backtick: find cluster containing start_idx
        for (s,e,close_a) in info.clusters:
            if s==start_idx:
                if e is not None: return e
                else: return len(segs)-1
        # if cluster not recorded, if unsafe treat as start_idx?
        if seg.type in ("var","cmdsubst","backtick"):
            return start_idx
        return start_idx

    def unit_end_ref(self,info):
        if not info.segments: return None
        # if first segment is cluster
        for (s,e,close_a) in info.clusters:
            if s==0:
                if close_a is not None: return close_a
                # else end segment last atom
                idx=e if e is not None else len(info.segments)-1
                seg=info.segments[idx]
                return seg.atoms[-1] if seg.atoms else None
        seg=info.segments[0]
        return seg.atoms[-1] if seg.atoms else None

    # --- for / case ---
    def parse_for_rest(self):
        # loop to find in / arith
        while True:
            # horizontal ws
            j=self.i
            while j<self.n and self.data[j] in WS_NO_NL: j+=1
            if j>self.i: self.emit(self.data[self.i:j],KEYWORD); self.i=j
            if self.i>=self.n:
                self.eof_error=True; return
            if self.data[self.i]==0x0a:
                return # body will handle newline
            if self.startswith(b"(("):
                self._parse_arith_segment(b"((",b"parens"); return
            if self.data[self.i:self.i+2]==b"in" and (self.i+2>=self.n or self.data[self.i+2] not in IDENT_CONT):
                self.emit(b"in",NORMAL); self.i+=2
                self.parse_for_list(); return
            if self.data[self.i] in IDENT_START:
                j=self.i
                while j<self.n and self.data[j] in IDENT_CONT: j+=1
                self.emit(self.data[self.i:j],ASSIGN); self.i=j; continue
            else:
                return

    def parse_for_list(self):
        ctx=BodyCtx(end_kind=None,initial_state="arg",for_list=True)
        res=self.parse_body(ctx)
        if res.reason=="eof":
            self.eof_error=True

    def parse_case_rest(self):
        # subject phase
        while True:
            j=self.i
            while j<self.n and self.data[j]<=0x20: j+=1
            if j>self.i: self.emit(self.data[self.i:j],KEYWORD); self.i=j
            if self.i>=self.n:
                self.eof_error=True; return
            if self.data[self.i:self.i+2]==b"in" and (self.i+2>=self.n or self.data[self.i+2] not in IDENT_CONT):
                # But this check happens after at least one subject? Original expects subject first.
                # We'll break only if we've already parsed a subject? Track with a flag outside? Simplify: if next is in and we are in loop after subject has been handled by code below...
                pass
            # parse a subject word then loop check for in after whitespace
            # peek for in before parsing if we have already parsed something? We'll maintain state in local variable
            break
        # Reimplement with state flag:
        parsed_subject=False
        while True:
            j=self.i
            while j<self.n and self.data[j]<=0x20: j+=1
            if j>self.i: self.emit(self.data[self.i:j],KEYWORD); self.i=j
            if self.i>=self.n:
                self.eof_error=True; return
            if parsed_subject and self.data[self.i:self.i+2]==b"in" and (self.i+2>=self.n or self.data[self.i+2] not in IDENT_CONT):
                self.emit(b"in",KEYWORD); self.i+=2; break
            # parse subject word
            info=self.parse_word("arg",BodyCtx(),mode_override="safe",plain_color_override=KEYWORD)
            if info.end==info.start and self.i<self.n:
                # consume one char as keyword to avoid loop
                self.emit(self.data[self.i:self.i+1],KEYWORD); self.i+=1
            parsed_subject=True
            if self.eof_error: return
        # pattern/body loop
        while True:
            if self.i>=self.n:
                self.eof_error=True; return
            # skip whitespace/comments
            if self.data[self.i]<=0x20:
                self.emit(self.data[self.i:self.i+1],NORMAL); self.i+=1; continue
            if self.data[self.i]==0x23:
                self.parse_comment(); continue
            # esac in pattern position
            if self.data[self.i:self.i+4]==b"esac" and (self.i+4>=self.n or self.data[self.i+4] not in IDENT_CONT):
                self.emit(b"esac",KEYWORD); self.i+=4; return
            if self.data[self.i]==0x28: # (
                self.emit(b"(",NORMAL); self.i+=1; continue
            # parse pattern word
            info=self.parse_word("arg",BodyCtx(),mode_override="safe",plain_color_override=NORMAL,extra=b")|")
            if self.i<self.n and self.data[self.i]==0x7c: # |
                self.emit(b"|",NORMAL); self.i+=1; continue
            if self.i<self.n and self.data[self.i]==0x29: # )
                self.emit(b")",NORMAL); self.i+=1
                res=self.parse_body(BodyCtx(end_kind=None,initial_state="cmd",case_body=True))
                if res.reason in ("case_terminator",):
                    continue
                elif res.reason=="case_esac":
                    return
                else:
                    self.eof_error=True; return
            if self.i>=self.n:
                self.eof_error=True; return
            # if no progress
            if info.end==info.start:
                self.emit(self.data[self.i:self.i+1],NORMAL); self.i+=1

    # --- body ---
    def parse_body(self,ctx):
        state=ctx.initial_state
        while True:
            if self.i>=self.n:
                if ctx.end_kind is not None and not ctx.lenient_eof:
                    self.eof_error=True
                return BodyResult("eof")
            c=self.data[self.i]
            # end terminator
            if ctx.end_kind is not None and c==ctx.end_kind[0] if isinstance(ctx.end_kind,bytes) else False:
                pass
            if ctx.end_kind==")" and c==0x29:
                self.emit(b")",NORMAL); self.i+=1; return BodyResult("closed")
            if ctx.end_kind=="`" and c==0x60:
                self.emit(b"`",NORMAL); self.i+=1; return BodyResult("closed")
            if ctx.end_kind=="]" and c==0x5d:
                self.emit(b"]",NORMAL); self.i+=1; return BodyResult("closed")
            if c==0x0a: # newline
                self.emit(b"\n",NORMAL); self.i+=1
                if ctx.for_list and ctx.for_words_seen>0:
                    return BodyResult("newline")
                state="cmd"; continue
            if c<=0x20: # other ws
                j=self.i
                while j<self.n and self.data[j]<=0x20 and self.data[j]!=0x0a: j+=1
                self.emit(self.data[self.i:j],NORMAL); self.i=j; continue
            if c==0x23: # #
                self.parse_comment(); continue
            if c==0x3b: # ;
                if ctx.case_body and self.startswith(b";;"):
                    self.emit(b";;",NORMAL); self.i+=2
                    if self.startswith(b";&"):
                        self.emit(b";&",NORMAL); self.i+=2
                    elif self.i<self.n and self.data[self.i]==0x26:
                        self.emit(b"&",NORMAL); self.i+=1
                    return BodyResult("case_terminator")
                self.emit(b";",NORMAL); self.i+=1
                if ctx.for_list:
                    return BodyResult("semicolon")
                state="cmd"; continue
            if c==0x26: # &
                if self.i+1<self.n and self.data[self.i+1]==0x26:
                    self.emit(b"&&",NORMAL); self.i+=2
                else:
                    self.emit(b"&",NORMAL); self.i+=1
                state="cmd"; continue
            if c==0x7c: # |
                if self.i+1<self.n and self.data[self.i+1]==0x7c:
                    self.emit(b"||",NORMAL); self.i+=2
                else:
                    self.emit(b"|",NORMAL); self.i+=1
                state="cmd"; continue
            if c==0x28: # (
                if state=="cmd":
                    if self.startswith(b"(("):
                        self._parse_arith_segment(b"((",b"parens"); state="cmd"; continue
                    else:
                        self.emit(b"(",NORMAL); self.i+=1
                        self.parse_body(BodyCtx(end_kind=")",initial_state="cmd"))
                        state="cmd"; continue
                else:
                    pass # fall to word
            if c in b"<>" :
                # process?
                if self.data[self.i:self.i+2] in (b"<(",b">("):
                    pass # to word
                elif self.startswith(b"<<<"):
                    self.emit(b"<<<",NORMAL); self.i+=3; continue
                elif self.startswith(b"<<"):
                    if state=="arg":
                        if self.try_heredoc():
                            continue
                        else:
                            self.emit(b"<<",NORMAL); self.i+=2; continue
                    else:
                        self.emit(b"<<",NORMAL); self.i+=2; continue
                elif self.data[self.i:self.i+2] in (b">>",b">&"):
                    self.emit(self.data[self.i:self.i+2],NORMAL); self.i+=2; continue
                else:
                    self.emit(bytes([c]),NORMAL); self.i+=1; continue
            # case esac detection
            if ctx.case_body and state=="cmd" and self.data[self.i:self.i+4]==b"esac" and (self.i+4>=self.n or self.data[self.i+4] not in IDENT_CONT):
                self.emit(b"esac",KEYWORD); self.i+=4; return BodyResult("case_esac")
            # special cmd constructs
            if state=="cmd":
                if self.data[self.i:self.i+2]==b"[[" and self.i+2<self.n and (self.data[self.i+2]<=0x20 or self.data[self.i+2] in b"()<>|&;`"):
                    self._parse_arith_segment(b"[[",b"brackets"); state="cmd"; continue
                if self.startswith(b"test ") or self.startswith(b"[ "):
                    self.parse_test_command(ctx); state="arg"; continue
            # word
            state_before=state
            info=self.parse_word(state,ctx)
            ctx.for_words_seen+=1
            if ctx.for_list and state_before=="arg":
                if ctx.for_arg_word_count==0:
                    ctx.for_arg_word_count+=1
                    self.maybe_for_array(info)
                else:
                    ctx.for_arg_word_count+=1
            # update state
            if state_before=="cmd":
                if info.type=="assignment":
                    state="cmd"
                elif info.type=="keyword":
                    state="cmd"
                elif info.type=="for":
                    self.parse_for_rest(); state="cmd"
                elif info.type=="case":
                    self.parse_case_rest(); state="cmd"
                else:
                    state="arg"
            else:
                state="arg"
            if self.eof_error and self.i>=self.n:
                # loop will return eof
                pass

    def maybe_for_array(self,info):
        if len(info.segments)!=1: return
        seg=info.segments[0]
        if seg.type!="var" or seg.braced or seg.safe or seg.star: return
        if not seg.simple_name: return
        # lookahead spaces then ; or newline
        k=self.i
        while k<self.n and self.data[k]==0x20: k+=1
        if k<self.n and self.data[k] in b";\n":
            # find closing quote insert atom: it's the atom after seg's last atom in global list? We inserted closing quote as emit ins at word end.
            # Search forward from seg last atom for an ins atom with text "
            if seg.atoms:
                idx=self.atoms.index(seg.atoms[-1])
                # find next ins " within a few atoms
                for j in range(idx+1,min(idx+4,len(self.atoms))):
                    if self.atoms[j].kind=="ins" and self.atoms[j].text==b'"':
                        self.atoms[j].text=b'[@]"'
                        break
                self.insert_after(seg.atoms[0],b"{")

    def process(self):
        try:
            self.parse_body(BodyCtx(end_kind=None,initial_state="cmd"))
        except Pitfall as e:
            return (e.pos,e.length)
        return None

