PITFALL_BODY = b"""This does not mean what it looks like. You may be forgiven to think that the full string of numerals is the variable name. Only the fist is.

Try this and be shocked: f() { echo "$9" "$10"; }; f a b c d e f g h i j

Here is where braces should be used to disambiguate, e.g. "${10}" vs "${1}0".

Syntactic pitfalls are deemed too dangerous to fix automatically
(the purpose of Shellharden is to fix vulnerable code \xe2\x80\x93 code that mostly does what it looks like, as opposed to code that never does what it looks like):
* Fixing what it does would be 100% subtle and might slip through code review unnoticed.
* Fixing its look would make a likely bug look intentional.
"""

EOF_MSG_BODY = b"The file's end was reached without closing all sytactic scopes.\nEither, the parser got lost, or the file is truncated or malformed.\n"

HELP_TEXT = b""

def format_error(fname_display,data,pitfall,eof_error):
    prefix=fname_display.encode('utf-8','replace')
    if pitfall is not None:
        pos,length=pitfall
        # find line
        line_start=data.rfind(b"\n",0,pos)+1
        line_end=data.find(b"\n",pos)
        if line_end<0: line_end=len(data)
        line=data[line_start:line_end]
        # decode as chars (utf-8 replace surrogateescape)
        text=line.decode('utf-8','surrogateescape')
        char_pos=len(data[line_start:pos].decode('utf-8','surrogateescape'))
        block_idx=char_pos//128
        block_start=block_idx*128
        block=text[block_start:block_start+128]
        caret_pos=char_pos-block_start
        caret=b" " * caret_pos + b"^"*length
        out=bytearray()
        out.extend(prefix+b": Unsupported syntax: Syntactic pitfall\n")
        out.extend(block.encode('utf-8','surrogateescape')+b"\n")
        out.extend(caret+b"\n")
        out.extend(PITFALL_BODY)
        return bytes(out)
    if eof_error:
        return prefix+b": Unexpected end of file\n"+EOF_MSG_BODY
