    try: data=open(f,'rb').read()
    except: continue
    if len(data)>200000: continue
    for mode in ["--transform","--syntax-suggest"]:
        total_modes+=1
        a=subprocess.run(["/workspace/executable",mode,""],input=data,capture_output=True)
        b=subprocess.run(["python3","/tmp/my.py",mode,""],input=data,capture_output=True)
        if (a.returncode,a.stdout,a.stderr)!=(b.returncode,b.stdout,b.stderr):
