files=sorted(glob.glob("/usr/local/go/src/*.bash")+glob.glob("/usr/local/go/src/*.sh")+glob.glob("/usr/share/*/*.sh")+glob.glob("/etc/profile.d/*.sh")+glob.glob("/usr/local/go/misc/**/*.sh",recursive=True))
