{"command":"python3 - << 'PY'
import pathlib
p=pathlib.Path("shellharden.py"); s=p.read_text()
old='''def out_write(bts):
    try:
        os.write(1,bts)
    except BrokenPipeError:
        pass
def err_write(bts):
    try:
        os.write(2,bts)
    except BrokenPipeError:
        pass'''
new='''def _write_all(fd,bts):
    mv=memoryview(bts)
    while len(mv)>0:
        try:
            k=os.write(fd,mv)
        except BrokenPipeError:
            return
        except InterruptedError:
            continue
        if k<=0: return
        mv=mv[k:]
def out_write(bts):
    _write_all(1,bts)
def err_write(bts):
    _write_all(2,bts)'''
assert old in s; s=s.replace(old,new)
p.write_text(s)
PY
cp shellharden.py /tmp/my.py
cat /tmp/big.sh | python3 /tmp/my.py --transform '' > /tmp/big_out.txt; cat /tmp/big.sh | ./executable --transform '' > /tmp/big_out2.txt; cmp /tmp/big_out.txt /tmp/big_out2.txt && echo big-ok"}

